1	package warranty
2	
3	import (
4		"fmt"
5		"sync"
6		"time"
7	)
8	
9	// Product 是登记的产品保修信息。
10	type Product struct {
11		// ID 是唯一产品编号。
12		ID string
13		// PurchaseTime 是购买时刻。
14		PurchaseTime time.Time
15		// WarrantyDays 是保修天数，必须为正整数；保修期自购买时刻起，每天按二十四小时计算。
16		WarrantyDays int
17		// ExcludedCodes 是除外故障代码集合；命中代码的请求一律拒绝。
18		ExcludedCodes map[string]struct{}
19	}
20	
21	// Part 是登记的备件及其库存。
22	type Part struct {
23		// ID 是唯一备件编号。
24		ID string
25		// Stock 是当前剩余实物库存，被成功使用的承诺分批扣减。
26		Stock int
27	}
28	
29	// Request 是提交的保修请求，指定产品和故障代码。
30	type Request struct {
31		// ID 是唯一请求编号。
32		ID string
33		// ProductID 是关联的产品编号。
34		ProductID string
35		// FaultCode 是故障代码，不能为空。
36		FaultCode string
37	}
38	
39	// CommitmentStatus 是承诺的当前状态。
40	type CommitmentStatus string
41	
42	const (
43		// CommitmentActive 表示承诺有效：未取消且未到期。
44		CommitmentActive CommitmentStatus = "active"
45		// CommitmentCanceled 表示承诺已被取消。
46		CommitmentCanceled CommitmentStatus = "canceled"
47		// CommitmentExpired 表示承诺已到期，余量自动释放。
48		CommitmentExpired CommitmentStatus = "expired"
49	)
50	
51	// Commitment 是一笔备件承诺。
52	type Commitment struct {
53		// ID 是全局唯一的提交编号。
54		ID string
55		// RequestID 是关联的请求编号。
56		RequestID string
57		// PartID 是预留的备件编号。
58		PartID string
59		// Quantity 是原定承诺数量（正整数）。
60		Quantity int
61		// Used 是已成功使用的累计数量。
62		Used int
63		// Expiry 是到期时刻；当前时刻等于或晚于它时承诺到期，余量释放。
64		Expiry time.Time
65		// Canceled 表示是否已被取消。
66		Canceled bool
67		// Expired 表示到期是否已被确认。到期确认是不可逆的结果：一经确认，
68		// 未用占用永久释放，之后即使传入更早的当前时刻也仍视为到期，不能重新
69		// 占用已释放给其他请求的数量。未确认前仅在当次时刻达到到期时刻时
70		// （库存查询、请求查询、新预留核算、新使用判断）就本次涉及的承诺确认。
71		// 幂等重试、参数非法或引用对象不存在而提前失败的调用不确认到期。
72		Expired bool
73	}
74	
75	// Unused 返回未用数量。
76	func (c *Commitment) Unused() int { return c.Quantity - c.Used }
77	
78	// confirmExpiryLocked 在已持锁的情况下按本次当前时刻确认单笔承诺到期。
79	// 仅确认本次操作涉及的承诺：未取消、尚未确认且当前时刻已达到到期时刻时
80	// 置位 Expired；该结果不可逆。已取消的承诺保持 canceled，不确认到期。
81	func (s *Store) confirmExpiryLocked(c *Commitment, now time.Time) {
82		if c.Canceled || c.Expired {
83			return
84		}
85		if !now.Before(c.Expiry) {
86			c.Expired = true
87		}
88	}
89	
90	// confirmPartExpiriesLocked 确认指定备件下全部已到期但尚未确认的承诺。
91	func (s *Store) confirmPartExpiriesLocked(partID string, now time.Time) {
92		for _, c := range s.commitments {
93			if c.PartID == partID {
94				s.confirmExpiryLocked(c, now)
95			}
96		}
97	}
98	
99	// confirmRequestExpiriesLocked 确认指定请求下全部已到期但尚未确认的承诺。
100	func (s *Store) confirmRequestExpiriesLocked(requestID string, now time.Time) {
101		for _, c := range s.commitments {
102			if c.RequestID == requestID {
103				s.confirmExpiryLocked(c, now)
104			}
105		}
106	}
107	
108	// Status 返回承诺的当前状态。
109	// 已确认到期不可逆：即使传入更早的当前时刻也显示 expired；状态不要求
110	// 调用时刻递增。取消优先于到期，已取消的记录始终显示 canceled。
111	func (c *Commitment) Status(now time.Time) CommitmentStatus {
112		switch {
113		case c.Canceled:
114			return CommitmentCanceled
115		case c.Expired:
116			return CommitmentExpired
117		case !now.Before(c.Expiry):
118			return CommitmentExpired
119		default:
120			return CommitmentActive
121		}
122	}
123	
124	// Usage 是一次成功的承诺使用记录。
125	type Usage struct {
126		// ID 是全局唯一的使用编号。
127		ID string
128		// CommitmentID 是被扣减的承诺编号。
129		CommitmentID string
130		// Quantity 是本次使用的正整数数量。
131		Quantity int
132	}
133	
134	// Store 保存全部登记信息与承诺。所有方法均为并发安全。
135	type Store struct {
136		mu          sync.Mutex
137		products    map[string]*Product
138		parts       map[string]*Part
139		requests    map[string]*Request
140		commitments map[string]*Commitment
141		usages      map[string]*Usage
142		// firstResults 保存每个承诺编号首次预留成功时返回的承诺快照（已用数量为零、
143		// 未取消）。原样重试取回它，不随分批使用、取消或到期改变。
144		firstResults map[string]Commitment
145		// history 保存按请求分组的预留处理历史，仅存在于当前仓库实例中。
146		history map[string][]HistoryRecord
147	}
148	
149	// NewStore 创建一个空的保修备件仓库。
150	func NewStore() *Store {
151		return &Store{
152			products:     make(map[string]*Product),
153			parts:        make(map[string]*Part),
154			requests:     make(map[string]*Request),
155			commitments:  make(map[string]*Commitment),
156			usages:       make(map[string]*Usage),
157			firstResults: make(map[string]Commitment),
158			history:      make(map[string][]HistoryRecord),
159		}
160	}
161	
162	// RegisterProduct 登记产品：购买时刻、保修天数和除外故障代码。
163	// 编号重复时返回 ErrDuplicateID 且保留原记录。保修天数必须为正整数，且自购买
164	// 时刻起完整天数（每天二十四小时）的截止时刻必须落在时间类型的可表示范围内，
165	// 否则返回 ErrInvalidParam，不保存产品记录。
166	func (s *Store) RegisterProduct(id string, purchaseTime time.Time, warrantyDays int, excludedCodes []string) error {
167		if id == "" {
168			return fmt.Errorf("%w: product id must not be empty", ErrInvalidParam)
169		}
170		if warrantyDays <= 0 {
171			return fmt.Errorf("%w: warranty days must be a positive integer", ErrInvalidParam)
172		}
173		// 截止时刻超出时间类型可表示范围的期限无法登记，不保存产品记录；
174		// 之后以同一编号提交可表示的条款仍可正常登记。
175		if _, ok := warrantyExpiry(purchaseTime, warrantyDays); !ok {
176			return fmt.Errorf("%w: warranty expiry for %d days is not representable", ErrInvalidParam, warrantyDays)
177		}
178		s.mu.Lock()
179		defer s.mu.Unlock()
180		if _, ok := s.products[id]; ok {
181			return fmt.Errorf("%w: product %q", ErrDuplicateID, id)
182		}
183		codes := make(map[string]struct{}, len(excludedCodes))
184		for _, c := range excludedCodes {
185			if c == "" {
186				return fmt.Errorf("%w: excluded fault code must not be empty", ErrInvalidParam)
187			}
188			codes[c] = struct{}{}
189		}
190		s.products[id] = &Product{
191			ID:            id,
192			PurchaseTime:  purchaseTime,
193			WarrantyDays:  warrantyDays,
194			ExcludedCodes: codes,
195		}
196		return nil
197	}
198	
199	// RegisterPart 登记备件及其非负整数初始库存。
200	// 编号重复时返回 ErrDuplicateID 且保留原记录。
201	func (s *Store) RegisterPart(id string, initialStock int) error {
202		if id == "" {
203			return fmt.Errorf("%w: part id must not be empty", ErrInvalidParam)
204		}
205		if initialStock < 0 {
206			return fmt.Errorf("%w: initial stock must be a non-negative integer", ErrInvalidParam)
207		}
208		s.mu.Lock()
209		defer s.mu.Unlock()
210		if _, ok := s.parts[id]; ok {
211			return fmt.Errorf("%w: part %q", ErrDuplicateID, id)
212		}
213		s.parts[id] = &Part{ID: id, Stock: initialStock}
214		return nil
215	}
216	
217	// SubmitRequest 提交保修请求，指定产品和故障代码。
218	// 编号重复时返回 ErrDuplicateID 且保留原记录。
219	func (s *Store) SubmitRequest(id, productID, faultCode string) error {
220		if id == "" {
221			return fmt.Errorf("%w: request id must not be empty", ErrInvalidParam)
222		}
223		if faultCode == "" {
224			return fmt.Errorf("%w: fault code must not be empty", ErrInvalidParam)
225		}
226		s.mu.Lock()
227		defer s.mu.Unlock()
228		if _, ok := s.requests[id]; ok {
229			return fmt.Errorf("%w: request %q", ErrDuplicateID, id)
230		}
231		s.requests[id] = &Request{ID: id, ProductID: productID, FaultCode: faultCode}
232		return nil
233	}
234	
235	// Product 返回指定编号的产品副本，不存在时返回 ErrNotFound。
236	func (s *Store) Product(id string) (Product, error) {
237		s.mu.Lock()
238		defer s.mu.Unlock()
239		p, ok := s.products[id]
240		if !ok {
241			return Product{}, fmt.Errorf("%w: product %q", ErrNotFound, id)
242		}
243		cp := *p
244		cp.ExcludedCodes = make(map[string]struct{}, len(p.ExcludedCodes))
245		for k := range p.ExcludedCodes {
246			cp.ExcludedCodes[k] = struct{}{}
247		}
248		return cp, nil
249	}
250	
251	// Part 返回指定编号的备件副本，不存在时返回 ErrNotFound。
252	func (s *Store) Part(id string) (Part, error) {
253		s.mu.Lock()
254		defer s.mu.Unlock()
255		p, ok := s.parts[id]
256		if !ok {
257			return Part{}, fmt.Errorf("%w: part %q", ErrNotFound, id)
258		}
259		return *p, nil
260	}
261	
262	// Request 返回指定编号的请求副本，不存在时返回 ErrNotFound。
263	func (s *Store) Request(id string) (Request, error) {
264		s.mu.Lock()
265		defer s.mu.Unlock()
266		r, ok := s.requests[id]
267		if !ok {
268			return Request{}, fmt.Errorf("%w: request %q", ErrNotFound, id)
269		}
270		return *r, nil
271	}
272	
273	// Commitment 返回指定编号的承诺副本，不存在时返回 ErrNotFound。
274	func (s *Store) Commitment(id string) (Commitment, error) {
275		s.mu.Lock()
276		defer s.mu.Unlock()
277		c, ok := s.commitments[id]
278		if !ok {
279			return Commitment{}, fmt.Errorf("%w: commitment %q", ErrNotFound, id)
280		}
281		return *c, nil
282	}
