	}
	if err := s.RegisterPart("part2", -1); !errors.Is(err, ErrInvalidParam) {
		t.Fatalf("negative stock: got %v", err)
	}
	if err := s.SubmitRequest("", "p1", "F"); !errors.Is(err, ErrInvalidParam) {
